import{_ as a,c as e,o as n,ag as t}from"./chunks/framework.DmF2n0Fc.js";const u=JSON.parse('{"title":"Model Context Protocol (MCP) Server","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://www.agnosticui.com/docs/mcp-server"}]]},"headers":[],"relativePath":"docs/mcp-server.md","filePath":"docs/mcp-server.md"}'),i={name:"docs/mcp-server.md"};function o(l,s,r,p,c,d){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="model-context-protocol-mcp-server" tabindex="-1">Model Context Protocol (MCP) Server <a class="header-anchor" href="#model-context-protocol-mcp-server" aria-label="Permalink to &quot;Model Context Protocol (MCP) Server&quot;">​</a></h1><p><strong>AgnosticUI MCP Server</strong> is a local workflow context engine that implements the open <strong>Model Context Protocol (MCP)</strong> specification. It bridges framework-agnostic design artifacts, Style Dictionary token registers, and Lit components directly into local AI-native coding environments.</p><p>By exposing these systems directly over standard input/output channels, an LLM shifts from blind guessing to zero-drift code generation—completely eliminating prop hallucinations and styling drift during software workflows.</p><div class="tip custom-block"><p class="custom-block-title">Early access</p><p>The MCP Server is new and evolving. The server architecture is stable enough to test and build with locally, but not yet published to npm. Feedback welcome via <a href="https://github.com/AgnosticUI/agnosticui/issues" target="_blank" rel="noreferrer">GitHub issues</a>.</p></div><hr><h2 id="exposed-tool-capabilities" tabindex="-1">Exposed Tool Capabilities <a class="header-anchor" href="#exposed-tool-capabilities" aria-label="Permalink to &quot;Exposed Tool Capabilities&quot;">​</a></h2><p>The background process provides four core tool capabilities to host AI applications:</p><table class="ag-table ag-table--striped"><thead><tr><th>Tool Name</th><th>Operational Intent</th><th>What it Returns</th></tr></thead><tbody><tr><td><code>get_component_schema</code></td><td>Resolves public element signatures</td><td>Precise slots, observed attributes, and framework-appropriate import syntax statements.</td></tr><tr><td><code>generate_streamed_layout</code></td><td>Pre-flight SDUI graph validator</td><td>A multi-pass topological audit block exposing structural errors or dangling parent-child reference pointers.</td></tr><tr><td><code>get_design_tokens</code></td><td>Style Dictionary primitivization</td><td>Natively resolved nested token objects (colors, spacing sizing grids, radii variables, motion).</td></tr><tr><td><code>resolve_skin_properties</code></td><td>Artistic theme sheet tracker</td><td>A key-value store mapping explicit custom property variables (<code>--ag-*</code>) modified by specialized visual sub-skins.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Local and Private</p><p>The server runs entirely on your local machine. Combined with local LLM runners like Ollama, you can execute tool-calling workflows, look up design tokens, and analyze component structures 100% offline with zero external cloud subscriptions.</p></div><hr><h2 id="architectural-workflow" tabindex="-1">Architectural Workflow <a class="header-anchor" href="#architectural-workflow" aria-label="Permalink to &quot;Architectural Workflow&quot;">​</a></h2><p>The background process connects smoothly to host environments or testing scripts using JSON-RPC communication envelopes over standard <code>stdio</code> text streams:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────┐</span></span>
<span class="line"><span>│   Host Local AI Assistant    │</span></span>
<span class="line"><span>│ (Claude Code, Ollama Harness)│</span></span>
<span class="line"><span>└──────────────▲───────────────┘</span></span>
<span class="line"><span>               │ (JSON-RPC over stdio)</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ AGNOSTICUI MCP SERVER                                                  │</span></span>
<span class="line"><span>│                                                                        │</span></span>
<span class="line"><span>│ ┌────────────────────────┐ ┌────────────────────────────┐              │</span></span>
<span class="line"><span>│ │ Tool Registry          │ │ Schema Validation Engine   │              │</span></span>
<span class="line"><span>│ │ (get_component_schema) │ │ (AJV / JSON Schema)        │              │</span></span>
<span class="line"><span>│ └───────────┬────────────┘ └─────────────┬──────────────┘              │</span></span>
<span class="line"><span>│             │                            │                             │</span></span>
<span class="line"><span>│             ▼                            ▼                             │</span></span>
<span class="line"><span>│ ┌────────────────────────┐ ┌────────────────────────────┐              │</span></span>
<span class="line"><span>│ │ Token Resolution Core  │ │ Workspace Context Discovery│              │</span></span>
<span class="line"><span>│ │ (Style Dictionary)     │ │ (agnosticui.config.json)   │              │</span></span>
<span class="line"><span>│ └────────────────────────┘ └────────────────────────────┘              │</span></span>
<span class="line"><span>└──────────────────────────────────────▲─────────────────────────────────┘</span></span>
<span class="line"><span>                                       │ (Local File System I/O)</span></span>
<span class="line"><span>                                       ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ LOCAL USER REPOSITORY WORKSPACE                                        │</span></span>
<span class="line"><span>│ │                                                                      │</span></span>
<span class="line"><span>│ ├── agnosticui.config.json ├── v2/lib/custom-elements.json             │</span></span>
<span class="line"><span>│ └── theme-registry/dist/   └── v2/skins/                               │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="data-freshness-synchronization" tabindex="-1">Data Freshness &amp; Synchronization <a class="header-anchor" href="#data-freshness-synchronization" aria-label="Permalink to &quot;Data Freshness &amp; Synchronization&quot;">​</a></h2><p>The validation checks verify the structural schema arrays (agnosticui-schema.json) and renderer mapping rules directly to flag pipeline deviations, rather than continuously monitoring the internal custom elements manifest file.</p><h3 id="manifest-synchronization-pipeline" tabindex="-1">Manifest Synchronization Pipeline <a class="header-anchor" href="#manifest-synchronization-pipeline" aria-label="Permalink to &quot;Manifest Synchronization Pipeline&quot;">​</a></h3><p>The critical component metadata file located at <code>v2/lib/custom-elements.json</code> captures every public attribute and component wrapper restriction. This is automatically kept up-to-date via an AST morphing compilation pipeline tied to a hard automated CI gate check (<code>npm run check-codegen</code>), stopping any configuration drift before code gets generated.</p><hr><h2 id="local-development-playground" tabindex="-1">Local Development Playground <a class="header-anchor" href="#local-development-playground" aria-label="Permalink to &quot;Local Development Playground&quot;">​</a></h2><p>A localized, offline test harness is bundled inside the server directory to quickly verify tool execution streams using small, lightweight models.</p><h3 id="task-automation-shorthand-commands" tabindex="-1">Task Automation Shorthand Commands <a class="header-anchor" href="#task-automation-shorthand-commands" aria-label="Permalink to &quot;Task Automation Shorthand Commands&quot;">​</a></h3><p>Execute the following automated scripts from the <code>v2/mcp-server/</code> directory to manage compiling, testing, or offline conversation evaluation loops:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># Evaluate TypeScript boundaries strictly without compiling code assets</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">npm</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> run</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> typecheck</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># Run continuous programmatic Vitest integration suites</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">npm</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> run</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> test</span></span></code></pre></div><h3 id="prerequisites-for-local-sandbox-executions" tabindex="-1">Prerequisites for Local Sandbox Executions <a class="header-anchor" href="#prerequisites-for-local-sandbox-executions" aria-label="Permalink to &quot;Prerequisites for Local Sandbox Executions&quot;">​</a></h3><p>Before running localized tool testing scripts (<code>npm run test:local</code>), you must install and start the Ollama service on your local environment:</p><ol><li>Download the executable bundle directly from <a href="https://ollama.com" target="_blank" rel="noreferrer">ollama.com</a>.</li><li>Start the desktop client background process.</li><li>Pre-pull the required models from your terminal layout window using the following commands:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">ollama</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> pull</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> qwen2.5-coder:1.5b</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">ollama</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> pull</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> llama3.2:latest</span></span></code></pre></div></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># Compile code deltas and launch an offline multi-turn conversation playground with Qwen 1.5B</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">npm</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> run</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> test:local</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># Compile code changes and dynamically run the sandbox loop against Llama 3.2</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">npm</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> run</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> test:local:watch</span></span></code></pre></div><p>When you trigger <code>npm run test:local</code>, your terminal manages the full tool loop transaction cleanly without internet dependencies:</p><ol><li>It reads your project&#39;s anchor <code>agnosticui.config.json</code> profile file.</li><li>It structures and passes the JSON-Schema parameters to <strong>Ollama</strong>.</li><li>The compact local model determines which capability it needs, handles markdown block clean-ups, and executes the underlying server code paths to inspect and output your actual design system variables.</li></ol>`,30)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
